const wrapRegistration = (originalFn: any, type: string) => {
  return (...args: any[]) => {
    const config = args[0];
    const name = config.name;
    const actionId = `/${type}/${name}`;

    // Track secondary IDs that Genkit creates automatically to suppress their logs too
    const secondaryId = type === 'prompt' ? `/executable-prompt/${name}` : 
                       type === 'tool' ? `/tool.v2/${name}` : null;

    if (registeredActions.has(actionId)) {
      try {
        const action = aiInstance.registry.lookupAction(actionId);
        // Genkit define methods return a callable function.
        // lookupAction returns the Action object. We wrap it in a callable that uses ai.run.
        const callable = (input: any) => aiInstance.run(action, input);
        // Copy metadata from the action to the callable for compatibility
        Object.assign(callable, action);
        return callable;
      } catch (e) {
        return originalFn.apply(aiInstance, args);
      }
    }

    registeredActions.add(actionId);
    if (secondaryId) registeredActions.add(secondaryId);

    return originalFn.apply(aiInstance, args);
  };
};

