/**
 * Global Singleton Pattern for Genkit
 * Prevents multiple instances and SIGINT listener accumulation during Next.js hot reloads.
 */
const globalForAi = globalThis as unknown as {
  ai: any | undefined;
};

// Server-only initialization
let aiInstance: any = null;

if (typeof window === 'undefined') {
  const { genkit } = require('genkit');
  const { ollama } = require('genkitx-ollama');

  // Skip if we are being bundled for a client-side environment that doesn't support genkit
  // This is a safety measure for Turbopack/Webpack
  aiInstance = globalForAi.ai ?? genkit({
    plugins: [
      ollama({
        models: [
          {
            name: 'gemma:2b',
            type: 'generate',
          },
          {
            name: 'phi4-mini:latest',
            type: 'generate',
          },
          {
            name: 'llama2:7b',
            type: 'generate',
          },
        ],
        serverAddress: process.env.OLLAMA_BASE_URL || "https://11434-01kn7zsd6et66g3qhpgssy1bzk.cloudspaces.litng.ai",
      }),
    ],
  });

  if (process.env.NODE_ENV !== 'production') {
    globalForAi.ai = aiInstance;
  }

  // Wrap registration methods to suppress "Overwriting" warnings during HMR
  if (aiInstance) {
    const globalStorage = globalThis as any;

    // Initialize global storage if it doesn't exist
    if (!globalStorage.__genkitRegisteredActions) {
      globalStorage.__genkitRegisteredActions = new Set<string>();
    }
    if (!globalStorage.__genkitCallables) {
      globalStorage.__genkitCallables = new Map<string, any>();
    }

    const callables = globalStorage.__genkitCallables;

    const wrapRegistration = (originalFn: any, type: string) => {
      return (...args: any[]) => {
        const config = args[0];
        const name = config.name;
        const actionId = `/${type}/${name}`;

        // If we already have a cached callable from a previous registration, return it.
        // This avoids calling originalFn (e.g. ai.defineFlow) which would trigger the "Overwriting" warning.
        if (callables.has(actionId)) {
          return callables.get(actionId);
        }

        const result = originalFn.apply(aiInstance, args);
        callables.set(actionId, result);
        return result;
      };
    };

    aiInstance.defineFlow = wrapRegistration(aiInstance.defineFlow.bind(aiInstance), 'flow');
    aiInstance.definePrompt = wrapRegistration(aiInstance.definePrompt.bind(aiInstance), 'prompt');
    aiInstance.defineTool = wrapRegistration(aiInstance.defineTool.bind(aiInstance), 'tool');
  }
}

export const ai = aiInstance;

// Re-export constants from domain
export * from "../../domain/constants/AiModels";

